// CS413 Lab 9 - Gyroscope parameters, Option A (open loop, in-place rotation).
// JavaScript generated by TRIK Studio from lab9_gyro.qrs and run on the robot.
// Warm-up 2 min, static 3 min, sin 36 s, rect 36 s (A = 30/60/150 %), rest 3 s.
// Log every loop: t_ms,t_us,gz_raw,gz_cal,encL,encR,u,phase (phase 0 static, 1 sin, 2 rect, 3 rest).
// Run 1 wrote lab9_gyro_real.csv, run 2 lab9_gyro_run2.csv (only the file name differs).

var __interpretation_started_timestamp__;
var pi = 3.141592653589793;
var amp;
var ampl;
var f;
var gz_raw;
var k;
var n;
var row;
var str;
var t;
var t0;
var tau;
var u;
var w;

var main = function()
{
	__interpretation_started_timestamp__ = Date.now();

	script.removeFile("lab9_gyro_run2.csv");

	brick.encoder(E3).reset();
	brick.encoder(E4).reset();

	amp = [ 30, 60, 150 ];
	str = "t_ms,t_us,gz_raw,gz_cal,encL,encR,u,phase\n";
	row = "";
	n = 0;
	u = 0;
	k = 0;
	gz_raw = 0;
	t = 0;
	t0 = 0;
	brick.display().addLabel("Warm-up 2 min: do not touch", 5, 5, 20);
	brick.display().redraw();

	script.wait(120000);

	brick.display().addLabel("Static 3 min, then rotation 72 s", 5, 5, 20);
	brick.display().redraw();

	t0 = (Date.now() - __interpretation_started_timestamp__);

	while (t < 255000) {
		t = (Date.now() - __interpretation_started_timestamp__) - t0;
		k = Math.min(1, Math.floor(t / 180000)) * Math.min(3, 1 + Math.floor(Math.max(0, t - 180000) / 36000));
		tau = t - 144000 - 36000 * k;
		ampl = amp[Math.min(2, Math.floor(Math.max(0, tau) / 12000))];
		f = Math.sin(2 * pi * tau / 4000);
		w = (2 - k) * f + (k - 1) * (function (x) { return (x > 0) - (x < 0) } (f));
		u = Math.floor(k * (3 - k) / 2 * Math.max(-100, Math.min(100, ampl * w)) + 0.5);
		brick.motor(M4).setPower(u);

		brick.motor(M3).setPower(-u);

		gz_raw = brick.gyroscope().readRawData()[2];

		row = t + "," + brick.gyroscope().read()[3] + "," + gz_raw + "," + brick.gyroscope().read()[2];
		str = str + row + "," + brick.encoder(E3).read() + "," + brick.encoder(E4).read() + "," + u + "," + k + "\n";
		n = n + 1;
		if (n >= 100) {
			script.writeToFile("lab9_gyro_run2.csv", str);

			str = "";
			n = 0;
		}
		script.wait(10);

	}
	brick.motor(M3).setPower(0);
	brick.motor(M4).setPower(0);

	script.writeToFile("lab9_gyro_run2.csv", str);

	brick.display().addLabel("Done: measure angle to tape", 5, 5, 20);
	brick.display().redraw();

	script.wait(5000);

	return;
}
